arguments.new_str:
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<TicketClassifierService>();

// Train the model at startup
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
TrainModel(dataPath, modelPath);

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/api/tickets/classify", (TicketRequest request, PredictionEnginePool<TicketData, TicketPrediction> pool) =>
{
    var input = new TicketData
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority
    };

    var prediction = pool.Predict(input);

    var labels = new[] { "Billing", "General", "Technical" };
    var scores = new Dictionary<string, float>();
    for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
    {
        scores[labels[i]] = prediction.Score[i];
    }

    return Results.Ok(new TicketPredictionResponse
    {
        PredictedCategory = prediction.Category,
        Scores = scores
    });
});

app.MapPost("/api/tickets/train", (TicketClassifierService service) =>
{
    var metrics = service.TrainAndEvaluate();
    return Results.Ok(metrics);
});

app.Run();

